-- REVIEW ONLY. Target pos / qhrufhtbeguxydenzfey, ROSEGILL org bjxgimekljzlnwejuawj.
-- Frozen 2026-10-29 cohort: 594 IDs. Requires separate owner approval before execution.
-- Existing version/time/history/feed triggers remain enabled. No schema changes.
BEGIN;
SET LOCAL lock_timeout = '3s';
SET LOCAL statement_timeout = '30s';
SELECT set_config('pos.source_application','approved-str1-archive-ownership-repair',true);
CREATE TEMP TABLE archive_repair_manifest(id uuid PRIMARY KEY, fingerprint text NOT NULL) ON COMMIT DROP;
-- Prevent concurrent reassignment of the target branch to a different cluster.
SELECT id FROM public.stores WHERE id='a611a328-2217-4d77-944a-5f6a637d123b' FOR SHARE;
DO $preflight$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.stores WHERE id='a611a328-2217-4d77-944a-5f6a637d123b' AND code='STR1' AND group_id='361-degree-sports' AND is_active AND deleted_at IS NULL)
 THEN RAISE EXCEPTION 'Repair target branch or cluster changed'; END IF;
 IF (SELECT count(*) FROM archive_repair_manifest)<>594 THEN RAISE EXCEPTION 'Invalid repair manifest'; END IF;
END $preflight$;
-- Lock only the reviewed records, never every product or any sale.
SELECT p.id FROM public.products p JOIN archive_repair_manifest m ON m.id=p.id ORDER BY p.id FOR UPDATE OF p;
CREATE TEMP TABLE archive_repair_before ON COMMIT DROP AS
SELECT p.id,to_jsonb(p) AS before_image FROM public.products p JOIN archive_repair_manifest m ON m.id=p.id;
DO $validate$
BEGIN
 IF (SELECT count(*) FROM archive_repair_before)<>594 THEN RAISE EXCEPTION 'A reviewed product is missing'; END IF;
 IF EXISTS(SELECT 1 FROM public.products p JOIN archive_repair_manifest m ON m.id=p.id
 WHERE md5(to_jsonb(p)::text)<>m.fingerprint OR p.owner_store_id IS NOT NULL OR p.is_archived IS NOT TRUE OR p.deleted_at IS NOT NULL OR p.stock_quantity IS DISTINCT FROM 0::numeric
 OR p.stock_by_store IS DISTINCT FROM public.canonical_stock_by_store(p.stock_by_store)
 OR p.catalogue_store_ids IS DISTINCT FROM public.received_product_catalogue_stores(p.id)
 OR p.stock_quantity IS DISTINCT FROM (SELECT COALESCE(sum(CASE WHEN jsonb_typeof(value)='number' THEN (value #>> '{}')::numeric ELSE 0 END),0) FROM jsonb_each(public.canonical_stock_by_store(p.stock_by_store))))
 THEN RAISE EXCEPTION 'Candidate changed or trigger preconditions differ; no repair applied'; END IF;
END $validate$;
UPDATE public.products p SET owner_store_id='a611a328-2217-4d77-944a-5f6a637d123b'
FROM archive_repair_manifest m WHERE p.id=m.id;
DO $verify$
BEGIN
 IF (SELECT count(*) FROM public.products p JOIN archive_repair_before b ON b.id=p.id)<>594
 THEN RAISE EXCEPTION 'A repaired product disappeared; repair rolled back'; END IF;
 IF EXISTS(SELECT 1 FROM public.products p JOIN archive_repair_before b ON b.id=p.id
 WHERE p.owner_store_id IS DISTINCT FROM 'a611a328-2217-4d77-944a-5f6a637d123b'
 OR (to_jsonb(p)-'owner_store_id'-'row_version'-'updated_at') IS DISTINCT FROM (b.before_image-'owner_store_id'-'row_version'-'updated_at')
 OR NOT public.product_available_in_catalogue(p.id,'a611a328-2217-4d77-944a-5f6a637d123b'))
 THEN RAISE EXCEPTION 'Unexpected field or visibility change; repair rolled back'; END IF;
END $verify$;
-- Return before/after images for secure capture and a separately reviewed guarded rollback.
SELECT p.id,b.before_image,to_jsonb(p) AS after_image FROM public.products p JOIN archive_repair_before b ON b.id=p.id ORDER BY p.id;
COMMIT;
